import * as THREE from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Apply scene placement
  group.position.set(-2.5, 1.6, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  let mesh = null;
  const timelines = [];
  let hoverTimeline = null;
  const originalPosition = { y: 1.6 };

  // Load GLB mesh
  if (config.meshUrl) {
    const glb = ctx.glbLoader(config.meshUrl);
    mesh = glb.scene.clone();
    group.add(mesh);
  }

  // Event handlers
  const handlers = {
    hover: (isHovering) => {
      if (hoverTimeline) hoverTimeline.kill();

      if (isHovering) {
        // Rise-in: move up 0.15 units with power3.out easing
        hoverTimeline = gsap.to(group.position, {
          y: originalPosition.y + 0.15,
          duration: 0.7,
          ease: 'power3.out'
        });
      } else {
        // Return to original with weighted-settle
        hoverTimeline = gsap.to(group.position, {
          y: originalPosition.y,
          duration: 0.9,
          ease: 'power4.out'
        });
      }
      timelines.push(hoverTimeline);
    },

    click: () => {
      // Press-down effect: scale down to 0.97
      const pressTimeline = gsap.to(group.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'back.out',
        yoyo: true,
        repeat: 1
      });
      timelines.push(pressTimeline);

      // Emit selection event
      if (config.onEvent) {
        config.onEvent('hub-home.select');
      }
    },

    focus: () => {
      // Accent edge on focus
      const accentColor = new THREE.Color(0xff2a38);
      if (mesh) {
        mesh.traverse((child) => {
          if (child.isMesh && child.material) {
            const mat = child.material;
            if (!mat._originalEmissive) {
              mat._originalEmissive = mat.emissive.getHex();
            }
            mat.emissive.copy(accentColor);
            mat.emissiveIntensity = 0.3;
          }
        });
      }
    },

    blur: () => {
      // Remove accent edge
      if (mesh) {
        mesh.traverse((child) => {
          if (child.isMesh && child.material) {
            const mat = child.material;
            if (mat._originalEmissive !== undefined) {
              mat.emissive.setHex(mat._originalEmissive);
            } else {
              mat.emissive.set(0x000000);
            }
            mat.emissiveIntensity = 0;
          }
        });
      }
    }
  };

  // Apply cinematic primitive: parallax-scroll
  if (ctx.primitives && typeof ctx.primitives['parallax-scroll'] === 'function') {
    ctx.primitives['parallax-scroll'](group, {
      intensity: 0.25,
      trigger: 'scroll'
    });
  }

  // Attach handlers and cleanup function
  group.userData = {
    handlers,
    cleanup() {
      // Kill all GSAP timelines
      timelines.forEach(tl => tl && tl.kill());
      if (hoverTimeline) hoverTimeline.kill();

      // Dispose mesh resources
      if (mesh) {
        mesh.traverse((child) => {
          if (child.geometry) child.geometry.dispose();
          if (child.material) {
            if (Array.isArray(child.material)) {
              child.material.forEach(m => m.dispose());
            } else {
              child.material.dispose();
            }
          }
        });
      }
    }
  };

  return group;
}
